def shade_row(counts: list[int], max_iter: int) -> str:
    """Map escape counts to PALETTE characters (glue: uses the module-level palette string)."""
    out = []
    for c in counts:
        out.append(PALETTE[min(len(PALETTE) - 1, c * len(PALETTE) // (max_iter + 1))])
    return "".join(out)
